<?php
 namespace Pterodactyl\Services\Dezerx\AutoAction; use Carbon\CarbonImmutable; use Pterodactyl\Models\Server; use Pterodactyl\Services\Dezerx\Addons; use Pterodactyl\Models\Dezerx\AutoAction; class AutoActions { public const SUSPEND = 'suspend'; public const DELETE = 'delete'; public const FORCE_DELETE = 'force_delete'; public const ACTIONS = [ self::SUSPEND => 'Suspend the server', self::DELETE => 'Delete the server', self::FORCE_DELETE => 'Force delete the server', ]; public const ACTION_HINTS = [ self::SUSPEND => 'The server stops and its owner loses access, but every file, database and backup stays where it is. Nothing is destroyed, and an administrator can unsuspend it later.', self::DELETE => 'The server is removed from the panel and from its node, along with its databases and its files. If the node cannot be reached the deletion is abandoned and retried, so nothing is half-removed.', self::FORCE_DELETE => 'The same, except node and database errors are ignored and the server is removed from the panel regardless. Files may be left behind on a node that was unreachable at the time.', ]; public const OUTCOME_SUSPENDED = 'suspended'; public const OUTCOME_ALREADY_SUSPENDED = 'already_suspended'; public const OUTCOME_DELETED = 'deleted'; public const OUTCOME_FORCE_DELETED = 'force_deleted'; public const OUTCOME_FAILED = 'failed'; public const MAX_ATTEMPTS = 5; private const MAX_TERM_DAYS = 3650; private const MAX_GRACE_MINUTES = 20160; public static function enabled(): bool { return (bool) (Addons::get(Addons::AUTO_ACTION)['enabled'] ?? false); } public static function action(?string $value): string { $value = str_replace('-', '_', mb_strtolower(trim((string) $value))); return array_key_exists($value, self::ACTIONS) ? $value : self::SUSPEND; } public static function chosen(?string $value): string { return trim((string) $value) === '' ? self::defaultAction() : self::action($value); } public static function label(?string $action): string { return self::ACTIONS[(string) $action] ?? (string) $action; } public static function defaultAction(): string { $stored = str_replace('-', '_', mb_strtolower(trim((string) (Addons::get(Addons::AUTO_ACTION)['default_action'] ?? '')))); return array_key_exists($stored, self::ACTIONS) ? $stored : self::SUSPEND; } public static function defaultTermDays(): ?int { $days = (int) trim((string) (Addons::get(Addons::AUTO_ACTION)['default_term_days'] ?? '')); if ($days < 1) { return null; } return min($days, self::MAX_TERM_DAYS); /* true */ } public static function graceMinutes(): int { $minutes = (int) trim((string) (Addons::get(Addons::AUTO_ACTION)['grace_minutes'] ?? '')); return max(0, min($minutes, self::MAX_GRACE_MINUTES)); } public static function suggestedDueAt(): ?CarbonImmutable { $days = self::defaultTermDays(); return $days === null ? null : CarbonImmutable::now(self::timezone())->addDays($days); } public static function timezone(): string { return (string) (config('app.timezone') ?: 'UTC'); } public static function forServer(Server $server): ?AutoAction { return AutoAction::query()->where('server_id', $server->id)->first(); } public static function parseDue(?string $value): ?CarbonImmutable { $value = trim((string) $value); if ($value === '') { return null; } try { return CarbonImmutable::parse($value, self::timezone()); } catch (\Throwable) { return null; } } public static function formatForInput(?\Carbon\CarbonInterface $moment): string { return $moment === null ? '' : CarbonImmutable::instance($moment)->setTimezone(self::timezone())->format('Y-m-d\TH:i'); } public static function set(Server $server, CarbonImmutable $due, string $action, ?int $authorId): AutoAction { $entry = self::forServer($server) ?? new AutoAction(['server_id' => $server->id]); $entry->forceFill([ 'server_id' => $server->id, 'created_by' => $authorId, 'due_at' => $due, 'action' => self::chosen($action), 'attempts' => 0, 'processed_at' => null, 'outcome' => null, 'failure' => null, ])->save(); return $entry; } public static function clear(Server $server): void { AutoAction::query()->where('server_id', $server->id)->delete(); } public static function fromRequest(Server $server, array $input, ?int $authorId): ?AutoAction { if (!self::enabled()) { return null; } $due = self::parseDue($input['due_at'] ?? null); if ($due === null) { self::clear($server); return null; } return self::set($server, $due, (string) ($input['action'] ?? ''), $authorId); } public static function describe(?AutoAction $entry): string { if ($entry === null) { return 'No auto action is set on this server.'; } $when = $entry->due_at?->setTimezone(self::timezone())->format('D j M Y, H:i') ?? 'an unknown time'; if (!$entry->isPending()) { $ran = $entry->processed_at?->setTimezone(self::timezone())->format('D j M Y, H:i') ?? $when; return self::label($entry->action) . ', ran ' . $ran . ' (' . ($entry->outcome ?? 'unknown') . ').'; } return self::label($entry->action) . ', due ' . $when . ' (' . self::timezone() . ').'; } } 